export const Icon: React.FC<IconProps> = ({ name, className = "w-5 h-5", size, ...props }) => {
  const dimensionProps = size ? { width: size, height: size } : {};
  const def = ICON_REGISTRY[name];
  if (def) {
    return (
      <svg
        viewBox={def.viewBox}
        fill="currentColor"
        className={className}
        {...dimensionProps}
        {...props}
      >
        <path d={def.d} />
      </svg>
    );
  }

  // Fallback clean geometric circle (never raw text ligature)
  return (
    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      className={className}
      {...dimensionProps}
      {...props}
    >
      <circle cx="12" cy="12" r="8" opacity="0.8" />
    </svg>
  );
};

export default Icon;
